//! ID-free stage configuration: element selectors resolved against the graph at stage time.
//!
//! A stage configuration value names PSG elements by ID. Many of those IDs are generated by
//! earlier stages, so a configuration written before the pipeline runs cannot know them. Any
//! position of a selectable configuration value that holds an ID (or an ID list) may instead
//! hold a selector:
//!
//! - `{"$one": QUERY}` is the ID of exactly one matching element (none or several is an error,
//!   except in a keyed entry list, see [`SelectorSchema::droppable`]);
//! - `{"$all": QUERY}` is the sorted list of every matching element; as an element of an ID
//!   list its IDs are spliced into that list.
//!
//! `QUERY` is `{"type": NodeType | [NodeType, ...], "where": {field: value, ...}}` (`where`
//! optional): the Accepted nodes of those types whose payload `data` fields equal the given JSON
//! values. Resolution is a pure function of the graph: the same graph always yields the same
//! IDs, and the resolved typed value (never the selector) is what the stage builds its requests
//! from, so a selector that resolves to the IDs an explicit configuration names produces the
//! same requests and request hashes. A value without selectors is the unchanged typed form.

use std::collections::BTreeSet;
use std::fmt;

use plumb_core::Id;
use plumb_psg::{ElementStatus, Graph, NodeType};
use serde::de::DeserializeOwned;
use serde::{Deserialize, Deserializer, Serialize, Serializer};
use serde_json::{json, Map, Value};

use crate::error::ApiError;

/// The ID a `$one` selector stands for while the shape of a value is checked without a graph.
const PLACEHOLDER: &str = "selector:placeholder";

/// How a selectable configuration type is checked and resolved. Paths name a position in the
/// value's JSON form: object keys joined by `.`, an array element written `[]` (for example
/// `sources[].source_ref`); the root is `""`.
pub trait SelectorSchema: Serialize + DeserializeOwned + Clone {
    /// The node types a selector at `path` may select; `None` leaves the position unchecked
    /// (the consumer still validates the resolved IDs).
    fn targets(_path: &str) -> Option<&'static [NodeType]> {
        None
    }

    /// Whether the array element at `path` is dropped when a `$one` inside it matches nothing:
    /// exactly the keyed entries whose explicit form ignores an ID naming no element.
    fn droppable(_path: &str) -> bool {
        false
    }

    /// Canonicalizes a resolved value whose consumer requires an order the configuration
    /// cannot know (IDs are not known in advance).
    fn normalize(&mut self) {}
}

/// Why a selector cannot be used.
#[derive(Debug, Clone, PartialEq)]
pub enum SelectorErrorKind {
    /// The selector itself is malformed or selects a node type the position does not admit.
    Invalid(String),
    /// A `$one` matched no element.
    Unmatched,
    /// A `$one` matched more than one element.
    Ambiguous(Vec<Id>),
    /// The resolved value is not a valid value of the configuration type.
    Shape(String),
}

/// A selector failure at a position of the configured value.
#[derive(Debug, Clone, PartialEq)]
pub struct SelectorError {
    pub path: String,
    pub selector: Value,
    pub kind: SelectorErrorKind,
}

impl fmt::Display for SelectorError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let at = if self.path.is_empty() {
            "the value".to_owned()
        } else {
            self.path.clone()
        };
        match &self.kind {
            SelectorErrorKind::Invalid(reason) => write!(f, "selector at {at}: {reason}"),
            SelectorErrorKind::Unmatched => {
                write!(f, "selector at {at} matches no element: {}", self.selector)
            }
            SelectorErrorKind::Ambiguous(ids) => write!(
                f,
                "selector at {at} matches {} elements, exactly one is required: {}",
                ids.len(),
                self.selector
            ),
            SelectorErrorKind::Shape(reason) => write!(f, "{at}: {reason}"),
        }
    }
}

impl std::error::Error for SelectorError {}

impl SelectorError {
    /// A resolved value that names the element `id` twice where it must be unique.
    pub fn duplicate(path: &str, id: &Id) -> SelectorError {
        SelectorError {
            path: path.to_owned(),
            selector: Value::Null,
            kind: SelectorErrorKind::Shape(format!("{id} is selected more than once")),
        }
    }

    /// 422 `E_STAGE_CONFIG_UNRESOLVED`: the configured `field` cannot be resolved against the
    /// graph the stage runs on.
    pub fn api_error(&self, field: &str) -> ApiError {
        let (kind, matches) = match &self.kind {
            SelectorErrorKind::Invalid(_) => ("invalid", Vec::new()),
            SelectorErrorKind::Unmatched => ("unmatched", Vec::new()),
            SelectorErrorKind::Ambiguous(ids) => ("ambiguous", ids.clone()),
            SelectorErrorKind::Shape(_) => ("shape", Vec::new()),
        };
        ApiError::unprocessable(
            "E_STAGE_CONFIG_UNRESOLVED",
            format!("the configured {field} cannot be resolved: {self}"),
        )
        .with_details(json!({
            "field": field,
            "path": self.path,
            "kind": kind,
            "selector": self.selector,
            "matches": matches,
        }))
    }
}

/// A configuration value that is either the explicit typed form or a template containing
/// selectors. It serializes as the configured JSON; [`Selectable::resolve`] yields the typed
/// value for one graph.
#[derive(Debug, Clone, PartialEq)]
pub struct Selectable<T> {
    configured: Value,
    explicit: Option<T>,
}

impl<T: Serialize> From<T> for Selectable<T> {
    fn from(value: T) -> Selectable<T> {
        let configured = serde_json::to_value(&value).unwrap_or(Value::Null);
        Selectable {
            configured,
            explicit: Some(value),
        }
    }
}

impl<T: Serialize + Default> Default for Selectable<T> {
    fn default() -> Selectable<T> {
        Selectable::from(T::default())
    }
}

impl<T> Selectable<T> {
    /// The configured JSON form (the template, for a selector form).
    pub fn configured(&self) -> &Value {
        &self.configured
    }

    /// The explicit typed value, when the configured value contains no selector.
    pub fn explicit(&self) -> Option<&T> {
        self.explicit.as_ref()
    }

    /// Whether the configured value contains at least one selector.
    pub fn has_selectors(&self) -> bool {
        self.explicit.is_none()
    }
}

impl<T: SelectorSchema> Selectable<T> {
    /// The eager check (no graph): every selector is well formed and admitted at its position,
    /// and the value has the shape of `T` once each selector stands for IDs.
    pub fn validate(&self) -> Result<(), SelectorError> {
        if self.explicit.is_some() {
            return Ok(());
        }
        let walker = Walker::<T>::new(None);
        let value = walker.value(&self.configured, "")?;
        decode::<T>(value).map(|_| ())
    }

    /// The typed value for `graph`. A dropped root (a keyed entry whose `$one` matches
    /// nothing) is an error here; see [`Selectable::resolve_entry`].
    pub fn resolve(&self, graph: &Graph) -> Result<T, SelectorError> {
        if let Some(value) = &self.explicit {
            return Ok(value.clone());
        }
        let walker = Walker::<T>::new(Some(graph));
        let mut value = decode::<T>(walker.value(&self.configured, "")?)?;
        value.normalize();
        Ok(value)
    }

    /// The typed value of one keyed entry for `graph`, or `None` when the entry names no
    /// element (exactly as an explicit entry naming an absent element is ignored).
    pub fn resolve_entry(&self, graph: &Graph) -> Result<Option<T>, SelectorError> {
        match self.resolve(graph) {
            Err(e) if e.kind == SelectorErrorKind::Unmatched && T::droppable("") => Ok(None),
            other => other.map(Some),
        }
    }
}

/// Decodes a resolved value strictly as `T`.
fn decode<T: DeserializeOwned>(value: Value) -> Result<T, SelectorError> {
    T::deserialize(value).map_err(|e| SelectorError {
        path: String::new(),
        selector: Value::Null,
        kind: SelectorErrorKind::Shape(e.to_string()),
    })
}

/// The path of an object member.
fn member(path: &str, key: &str) -> String {
    if path.is_empty() {
        key.to_owned()
    } else {
        format!("{path}.{key}")
    }
}

/// The path of an array element.
fn element(path: &str) -> String {
    format!("{path}[]")
}

/// One parsed selector.
enum Selector {
    One(Query),
    All(Query),
}

/// The node types and payload field values a selector matches.
struct Query {
    types: Vec<NodeType>,
    filter: Map<String, Value>,
}

/// Resolves (with a graph) or shape-checks (without one) the selectors of a value of `T`.
struct Walker<'g, T> {
    graph: Option<&'g Graph>,
    _schema: std::marker::PhantomData<T>,
}

impl<'g, T: SelectorSchema> Walker<'g, T> {
    fn new(graph: Option<&'g Graph>) -> Walker<'g, T> {
        Walker {
            graph,
            _schema: std::marker::PhantomData,
        }
    }

    fn invalid(path: &str, selector: &Value, reason: impl Into<String>) -> SelectorError {
        SelectorError {
            path: path.to_owned(),
            selector: selector.clone(),
            kind: SelectorErrorKind::Invalid(reason.into()),
        }
    }

    /// Parses the selector object `value` at `path`; `ids_path` is the path its IDs occupy
    /// (whose declared targets it must respect).
    fn parse(&self, value: &Value, path: &str, ids_path: &str) -> Result<Selector, SelectorError> {
        let Value::Object(map) = value else {
            return Err(Self::invalid(path, value, "a selector must be an object"));
        };
        if map.len() != 1 {
            return Err(Self::invalid(
                path,
                value,
                "a selector object has exactly one key, $one or $all",
            ));
        }
        let (key, query) = map.iter().next().expect("one key");
        let Value::Object(fields) = query else {
            return Err(Self::invalid(
                path,
                value,
                format!("the {key} query must be an object"),
            ));
        };
        if let Some(unknown) = fields.keys().find(|k| *k != "type" && *k != "where") {
            return Err(Self::invalid(
                path,
                value,
                format!("unknown query field {unknown:?} (allowed: type, where)"),
            ));
        }
        let names: Vec<&Value> = match fields.get("type") {
            Some(Value::String(_)) => vec![&fields["type"]],
            Some(Value::Array(items)) if !items.is_empty() => items.iter().collect(),
            _ => {
                return Err(Self::invalid(
                    path,
                    value,
                    "the query type must be a node type name or a non-empty list of them",
                ))
            }
        };
        let mut types = Vec::with_capacity(names.len());
        for name in names {
            let found = name
                .as_str()
                .and_then(|n| NodeType::ALL.iter().copied().find(|t| t.as_str() == n));
            let Some(node_type) = found else {
                return Err(Self::invalid(
                    path,
                    value,
                    format!("{name} is not a node type"),
                ));
            };
            if types.contains(&node_type) {
                return Err(Self::invalid(
                    path,
                    value,
                    format!("node type {} is listed twice", node_type.as_str()),
                ));
            }
            types.push(node_type);
        }
        if let Some(allowed) = T::targets(ids_path) {
            if let Some(bad) = types.iter().find(|t| !allowed.contains(t)) {
                let allowed: Vec<&str> = allowed.iter().map(|t| t.as_str()).collect();
                return Err(Self::invalid(
                    path,
                    value,
                    format!(
                        "{} cannot be selected here (allowed: {})",
                        bad.as_str(),
                        allowed.join(", ")
                    ),
                ));
            }
        }
        let filter = match fields.get("where") {
            None => Map::new(),
            Some(Value::Object(filter)) if !contains_selector(&Value::Object(filter.clone())) => {
                filter.clone()
            }
            Some(_) => {
                return Err(Self::invalid(
                    path,
                    value,
                    "the query where must be an object of literal payload field values",
                ))
            }
        };
        let query = Query { types, filter };
        match key.as_str() {
            "$one" => Ok(Selector::One(query)),
            "$all" => Ok(Selector::All(query)),
            other => Err(Self::invalid(
                path,
                value,
                format!("unknown selector {other} (allowed: $one, $all)"),
            )),
        }
    }

    /// The sorted IDs of the Accepted nodes `query` matches (empty without a graph).
    fn matches(&self, query: &Query) -> Vec<Id> {
        let Some(graph) = self.graph else {
            return Vec::new();
        };
        let mut ids = BTreeSet::new();
        for node_type in &query.types {
            for id in graph.node_ids_by_type(*node_type) {
                let Some(node) = graph.node(id) else { continue };
                if node.status != ElementStatus::Accepted {
                    continue;
                }
                if !query.filter.is_empty() {
                    let payload = serde_json::to_value(&node.payload).unwrap_or(Value::Null);
                    let data = &payload["data"];
                    if !query.filter.iter().all(|(k, v)| data.get(k) == Some(v)) {
                        continue;
                    }
                }
                ids.insert(id.clone());
            }
        }
        ids.into_iter().collect()
    }

    /// The ID of a `$one` selector.
    fn one(&self, query: &Query, path: &str, selector: &Value) -> Result<Value, SelectorError> {
        if self.graph.is_none() {
            return Ok(Value::String(PLACEHOLDER.to_owned()));
        }
        let mut ids = self.matches(query);
        let error = |kind| SelectorError {
            path: path.to_owned(),
            selector: selector.clone(),
            kind,
        };
        match ids.len() {
            0 => Err(error(SelectorErrorKind::Unmatched)),
            1 => Ok(Value::String(ids.remove(0).to_string())),
            _ => Err(error(SelectorErrorKind::Ambiguous(ids))),
        }
    }

    fn ids(ids: Vec<Id>) -> Vec<Value> {
        ids.into_iter()
            .map(|id| Value::String(id.to_string()))
            .collect()
    }

    /// The resolved form of `value` at `path`.
    fn value(&self, value: &Value, path: &str) -> Result<Value, SelectorError> {
        match value {
            Value::Object(map) if map.keys().any(|k| k.starts_with('$')) => {
                // A whole-list `$all`: its IDs are the elements of the list at `path`.
                let ids_path = if map.contains_key("$all") {
                    element(path)
                } else {
                    path.to_owned()
                };
                match self.parse(value, path, &ids_path)? {
                    Selector::One(query) => self.one(&query, path, value),
                    Selector::All(query) => Ok(Value::Array(Self::ids(self.matches(&query)))),
                }
            }
            Value::Object(map) => {
                let mut out = Map::new();
                for (key, item) in map {
                    out.insert(key.clone(), self.value(item, &member(path, key))?);
                }
                Ok(Value::Object(out))
            }
            Value::Array(items) => {
                let item_path = element(path);
                let mut out = Vec::with_capacity(items.len());
                for item in items {
                    if let Value::Object(map) = item {
                        if map.contains_key("$all") {
                            if let Selector::All(query) =
                                self.parse(item, &item_path, &item_path)?
                            {
                                out.extend(Self::ids(self.matches(&query)));
                                continue;
                            }
                        }
                    }
                    match self.value(item, &item_path) {
                        Ok(resolved) => out.push(resolved),
                        Err(e)
                            if e.kind == SelectorErrorKind::Unmatched
                                && T::droppable(&item_path) => {}
                        Err(e) => return Err(e),
                    }
                }
                Ok(Value::Array(out))
            }
            other => Ok(other.clone()),
        }
    }
}

impl<T: Serialize> Serialize for Selectable<T> {
    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        match &self.explicit {
            Some(value) => value.serialize(serializer),
            None => self.configured.serialize(serializer),
        }
    }
}

impl<'de, T: DeserializeOwned> Deserialize<'de> for Selectable<T> {
    /// A value without selectors is decoded strictly as `T` (the unchanged explicit form); a
    /// value with selectors is kept as its template and checked by [`Selectable::validate`]
    /// (the runtime validation, `E_RUNTIME_CONFIG_INVALID`).
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        let configured = Value::deserialize(deserializer)?;
        if contains_selector(&configured) {
            return Ok(Selectable {
                configured,
                explicit: None,
            });
        }
        let explicit = T::deserialize(configured.clone()).map_err(serde::de::Error::custom)?;
        Ok(Selectable {
            configured,
            explicit: Some(explicit),
        })
    }
}

/// Whether `value` holds an object with a `$`-prefixed key at any depth (the reserved selector
/// keys; no typed configuration field starts with `$`).
pub fn contains_selector(value: &Value) -> bool {
    match value {
        Value::Object(map) => {
            map.keys().any(|k| k.starts_with('$')) || map.values().any(contains_selector)
        }
        Value::Array(items) => items.iter().any(contains_selector),
        _ => false,
    }
}

// ============================================================================ stage resolution

/// The resolved typed value of the configured `field` for `graph` (422
/// `E_STAGE_CONFIG_UNRESOLVED` when it cannot be resolved).
pub(crate) fn resolve_field<T: SelectorSchema>(
    field: &str,
    value: Option<&Selectable<T>>,
    graph: &Graph,
) -> Result<Option<T>, ApiError> {
    value
        .map(|v| v.resolve(graph).map_err(|e| e.api_error(field)))
        .transpose()
}

/// The resolved entries of a keyed entry list: an entry whose selector names no element is
/// left out, exactly as an explicit entry naming an absent element is ignored.
pub(crate) fn resolve_entries<T: SelectorSchema>(
    field: &str,
    values: &[Selectable<T>],
    graph: &Graph,
) -> Result<Vec<T>, ApiError> {
    let mut out = Vec::with_capacity(values.len());
    for value in values {
        if let Some(entry) = value.resolve_entry(graph).map_err(|e| e.api_error(field))? {
            out.push(entry);
        }
    }
    Ok(out)
}

/// What a stage's selector-form configuration values were, recorded next to their resolved
/// values in the stage inputs (`inputs.selections`, only when a selector is configured), so
/// audit and replay show both what was configured and what it selected.
#[derive(Default)]
pub(crate) struct Selections(Map<String, Value>);

impl Selections {
    /// Records `value` under the inputs key `key` when it is a selector form.
    pub(crate) fn record<T>(&mut self, key: &str, value: Option<&Selectable<T>>) {
        if let Some(value) = value.filter(|v| v.has_selectors()) {
            self.0.insert(key.to_owned(), value.configured().clone());
        }
    }

    /// Records the configured entries under `key` when any entry is a selector form.
    pub(crate) fn record_entries<T>(&mut self, key: &str, values: &[Selectable<T>]) {
        if values.iter().any(Selectable::has_selectors) {
            let configured = values.iter().map(|v| v.configured().clone()).collect();
            self.0.insert(key.to_owned(), Value::Array(configured));
        }
    }

    /// `inputs` with the recorded selections; unchanged when nothing was a selector form.
    pub(crate) fn into_inputs(self, mut inputs: Value) -> Value {
        if !self.0.is_empty() {
            inputs["selections"] = Value::Object(self.0);
        }
        inputs
    }
}

// ============================================================================ schemas

const PERFORMERS: &[NodeType] = &[NodeType::Actor, NodeType::BusinessRole];
const SCENARIO_SOURCES: &[NodeType] = &[NodeType::Requirement, NodeType::Operation];

impl SelectorSchema for plumb_functional::OperationScope {
    fn targets(path: &str) -> Option<&'static [NodeType]> {
        Some(match path {
            "performer_refs[]" => PERFORMERS,
            "domain_refs[]" => &[NodeType::Entity, NodeType::Attribute],
            "calculation_refs[]" => &[NodeType::Calculation],
            "governor_refs[]" => &[NodeType::Rule, NodeType::DecisionTable],
            "event_refs[]" => &[NodeType::Event],
            "data_schema_refs[]" => &[NodeType::DataSchema],
            "event_payload_attribute_refs[]" => &[NodeType::Attribute],
            "support_refs[]" => &[
                NodeType::AcceptanceCriterion,
                NodeType::Invariant,
                NodeType::Rule,
                NodeType::DecisionTable,
                NodeType::Calculation,
            ],
            _ => return None,
        })
    }
}

impl SelectorSchema for plumb_functional::ProcessScope {
    fn targets(path: &str) -> Option<&'static [NodeType]> {
        Some(match path {
            "operation_refs[]" => &[NodeType::Operation],
            "performer_refs[]" => PERFORMERS,
            "event_refs[]" => &[NodeType::Event],
            "outcome_refs[]" => &[NodeType::Outcome],
            "transition_refs[]" => &[NodeType::Transition],
            _ => return None,
        })
    }
}

impl SelectorSchema for plumb_functional::CalculationScope {
    fn targets(path: &str) -> Option<&'static [NodeType]> {
        match path {
            "calendar_refs[]" => Some(&[NodeType::Calendar]),
            _ => None,
        }
    }
}

impl SelectorSchema for plumb_functional::AuthorizationDraft {}

impl SelectorSchema for plumb_functional::ScenarioDerivationInputs {
    /// Derivation requires its entries in canonical order, which a configuration naming
    /// elements by selector cannot know.
    fn normalize(&mut self) {
        let inputs = std::mem::replace(
            self,
            plumb_functional::ScenarioDerivationInputs::new(Vec::new(), Vec::new()),
        );
        *self = plumb_functional::ScenarioDerivationInputs::new(
            inputs.decision_tables,
            inputs.boundaries,
        );
    }
}

impl SelectorSchema for plumb_functional::VerificationApplicabilityInputs {
    fn targets(path: &str) -> Option<&'static [NodeType]> {
        match path {
            "sources[].source_ref" => Some(SCENARIO_SOURCES),
            _ => None,
        }
    }

    fn droppable(path: &str) -> bool {
        path == "sources[]"
    }
}

impl SelectorSchema for crate::runtime::F4GateConfig {
    fn targets(path: &str) -> Option<&'static [NodeType]> {
        Some(match path {
            "in_scope_scenario_refs[]" => &[NodeType::Scenario],
            "required_scenario_kinds[].source_ref" => SCENARIO_SOURCES,
            "visible_assumption_refs[]" => &[NodeType::Assumption],
            _ => return None,
        })
    }

    fn droppable(path: &str) -> bool {
        matches!(
            path,
            "in_scope_scenario_refs[]" | "required_scenario_kinds[]" | "visible_assumption_refs[]"
        )
    }
}

impl SelectorSchema for plumb_sim::ExecutionExpressionScopeInput {
    fn droppable(path: &str) -> bool {
        path.is_empty()
    }
}

impl SelectorSchema for plumb_sim::ExecutionCalculationScopeOverride {
    fn targets(path: &str) -> Option<&'static [NodeType]> {
        match path {
            "calculation_ref" => Some(&[NodeType::Calculation]),
            "scope.calendar_refs[]" => Some(&[NodeType::Calendar]),
            _ => None,
        }
    }

    fn droppable(path: &str) -> bool {
        path.is_empty()
    }
}

impl SelectorSchema for plumb_sim::RuntimeSemanticValue {
    fn droppable(path: &str) -> bool {
        path.is_empty()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use plumb_psg::Node;

    /// A test configuration type: an ID, an ID list and a keyed entry list.
    #[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
    #[serde(deny_unknown_fields)]
    struct Sample {
        one: Id,
        many: Vec<Id>,
        entries: Vec<Entry>,
    }

    #[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
    #[serde(deny_unknown_fields)]
    struct Entry {
        source_ref: Id,
        note: String,
    }

    impl SelectorSchema for Sample {
        fn targets(path: &str) -> Option<&'static [NodeType]> {
            match path {
                "many[]" => Some(&[NodeType::Entity, NodeType::Attribute]),
                _ => None,
            }
        }

        fn droppable(path: &str) -> bool {
            path == "entries[]"
        }

        fn normalize(&mut self) {
            self.entries.sort_by(|a, b| a.source_ref.cmp(&b.source_ref));
        }
    }

    fn id(s: &str) -> Id {
        s.parse().unwrap()
    }

    fn node(node_id: &str, status: &str, tag: &str, data: Value) -> Node {
        serde_json::from_value(json!({
            "id": node_id, "revision": 1, "status": status,
            "payload": {"type": tag, "data": data},
            "evidence": [], "derivations": [], "standards": [], "tags": [], "extensions": {},
            "audit": {"created_by": "agent:a", "created_at": "2026-01-01T00:00:00.000000000Z",
                      "updated_by": null, "updated_at": null}
        }))
        .unwrap_or_else(|e| panic!("{node_id}: {e}"))
    }

    fn attribute(node_id: &str, status: &str, name: &str) -> Node {
        node(
            node_id,
            status,
            "Attribute",
            json!({"name": name, "value_type": "String", "nullable": false, "unit": null,
                   "precision": null, "enum_values": null, "data_classification": null}),
        )
    }

    fn graph() -> Graph {
        let nodes = vec![
            node(
                "agent:a",
                "Accepted",
                "Agent",
                json!({"agent_kind": "human"}),
            ),
            node(
                "entity:b",
                "Accepted",
                "Entity",
                json!({"name": "Leave", "description": null, "aggregate_root": null}),
            ),
            attribute("attr:z-start", "Accepted", "start date"),
            attribute("attr:a-end", "Accepted", "end date"),
            attribute("attr:m-dup1", "Accepted", "duplicate"),
            attribute("attr:m-dup2", "Accepted", "duplicate"),
            attribute("attr:p-proposed", "Proposed", "proposed"),
        ];
        let edges = ["attr:z-start", "attr:a-end", "attr:m-dup1", "attr:m-dup2"]
            .iter()
            .enumerate()
            .map(|(i, to)| {
                serde_json::from_value(json!({
                    "id": format!("rel:{i}"), "revision": 1, "status": "Accepted",
                    "kind": "has_attribute", "from": "entity:b", "to": to, "properties": {},
                    "evidence": [], "derivations": [], "standards": [],
                    "audit": {"created_by": "agent:a",
                              "created_at": "2026-01-01T00:00:00.000000000Z",
                              "updated_by": null, "updated_at": null}
                }))
                .unwrap()
            })
            .collect();
        Graph::new(id("project:p"), id("profile:p"), nodes, edges).unwrap()
    }

    fn sample(value: Value) -> Selectable<Sample> {
        serde_json::from_value(value).unwrap()
    }

    fn one(name: &str) -> Value {
        json!({"$one": {"type": "Attribute", "where": {"name": name}}})
    }

    #[test]
    fn explicit_form_is_decoded_strictly_and_serialized_unchanged() {
        let value = json!({"one": "attr:x", "many": ["b:1", "a:1"], "entries": []});
        let s = sample(value.clone());
        assert!(!s.has_selectors());
        assert_eq!(serde_json::to_value(&s).unwrap(), value);
        assert_eq!(
            s.resolve(&graph()).unwrap().many,
            vec![id("b:1"), id("a:1")]
        );
        // Strict: an unknown field of the explicit form is a decode error, as before.
        let err = serde_json::from_value::<Selectable<Sample>>(
            json!({"one": "attr:x", "many": [], "entries": [], "extra": 1}),
        )
        .unwrap_err();
        assert!(err.to_string().contains("extra"), "{err}");
    }

    #[test]
    fn one_selects_the_single_accepted_match_by_payload_field() {
        let s = sample(json!({"one": one("start date"), "many": [], "entries": []}));
        assert!(s.has_selectors());
        s.validate().unwrap();
        assert_eq!(s.resolve(&graph()).unwrap().one, id("attr:z-start"));
        // The template is what is configured (and recorded).
        assert_eq!(s.configured()["one"], one("start date"));
    }

    #[test]
    fn all_selects_every_accepted_node_of_the_types_sorted() {
        let s = sample(json!({
            "one": "attr:x",
            "many": {"$all": {"type": ["Attribute", "Entity"]}},
            "entries": []
        }));
        s.validate().unwrap();
        let resolved = s.resolve(&graph()).unwrap();
        // Proposed nodes and other types are never selected; the order is the ID order.
        assert_eq!(
            resolved.many,
            [
                "attr:a-end",
                "attr:m-dup1",
                "attr:m-dup2",
                "attr:z-start",
                "entity:b"
            ]
            .map(id)
            .to_vec()
        );
    }

    #[test]
    fn all_inside_a_list_is_spliced_between_explicit_items() {
        let s = sample(json!({
            "one": "attr:x",
            "many": ["x:first", {"$all": {"type": "Entity"}}, one("end date")],
            "entries": []
        }));
        s.validate().unwrap();
        assert_eq!(
            s.resolve(&graph()).unwrap().many,
            ["x:first", "entity:b", "attr:a-end"].map(id).to_vec()
        );
    }

    #[test]
    fn resolution_is_deterministic_and_matches_the_explicit_form() {
        let selector = sample(json!({
            "one": one("start date"),
            "many": {"$all": {"type": "Entity"}},
            "entries": [{"source_ref": one("end date"), "note": "n"}]
        }));
        let explicit = sample(json!({
            "one": "attr:z-start",
            "many": ["entity:b"],
            "entries": [{"source_ref": "attr:a-end", "note": "n"}]
        }));
        let g = graph();
        let first = selector.resolve(&g).unwrap();
        assert_eq!(first, selector.resolve(&g).unwrap());
        assert_eq!(first, explicit.resolve(&g).unwrap());
        assert_eq!(
            serde_json::to_value(&first).unwrap(),
            serde_json::to_value(&explicit).unwrap()
        );
    }

    #[test]
    fn unmatched_and_ambiguous_one_are_errors_with_their_path() {
        let g = graph();
        let missing = sample(json!({"one": one("nothing"), "many": [], "entries": []}));
        let err = missing.resolve(&g).unwrap_err();
        assert_eq!(err.kind, SelectorErrorKind::Unmatched);
        assert_eq!(err.path, "one");
        // A Proposed node is not selectable.
        let proposed = sample(json!({"one": one("proposed"), "many": [], "entries": []}));
        assert_eq!(
            proposed.resolve(&g).unwrap_err().kind,
            SelectorErrorKind::Unmatched
        );
        let twice = sample(json!({"one": one("duplicate"), "many": [], "entries": []}));
        let err = twice.resolve(&g).unwrap_err();
        assert_eq!(
            err.kind,
            SelectorErrorKind::Ambiguous(vec![id("attr:m-dup1"), id("attr:m-dup2")])
        );
        let api = err.api_error("sample");
        assert_eq!(api.body().code, "E_STAGE_CONFIG_UNRESOLVED");
        assert_eq!(api.body().details["path"], "one");
        assert_eq!(api.body().details["kind"], "ambiguous");
        assert_eq!(
            api.body().details["matches"],
            json!(["attr:m-dup1", "attr:m-dup2"])
        );
    }

    #[test]
    fn an_unmatched_keyed_entry_is_dropped_like_an_absent_explicit_id() {
        let s = sample(json!({
            "one": "attr:x",
            "many": [],
            "entries": [
                {"source_ref": one("start date"), "note": "kept"},
                {"source_ref": one("nothing"), "note": "dropped"},
                {"source_ref": one("end date"), "note": "kept too"}
            ]
        }));
        let resolved = s.resolve(&graph()).unwrap();
        // Dropped, then normalized into the canonical order.
        assert_eq!(
            resolved
                .entries
                .iter()
                .map(|e| e.note.as_str())
                .collect::<Vec<_>>(),
            ["kept too", "kept"]
        );
        // Ambiguity is never dropped.
        let s = sample(json!({
            "one": "attr:x", "many": [],
            "entries": [{"source_ref": one("duplicate"), "note": "n"}]
        }));
        assert!(matches!(
            s.resolve(&graph()).unwrap_err().kind,
            SelectorErrorKind::Ambiguous(_)
        ));
    }

    #[test]
    fn a_dropped_root_entry_resolves_to_none() {
        let entry: Selectable<Entry> =
            serde_json::from_value(json!({"source_ref": one("nothing"), "note": "n"})).unwrap();
        assert_eq!(entry.resolve_entry(&graph()).unwrap(), None);
        assert_eq!(
            entry.resolve(&graph()).unwrap_err().kind,
            SelectorErrorKind::Unmatched
        );
        let entry: Selectable<Entry> =
            serde_json::from_value(json!({"source_ref": one("end date"), "note": "n"})).unwrap();
        assert_eq!(
            entry.resolve_entry(&graph()).unwrap().unwrap().source_ref,
            id("attr:a-end")
        );
    }

    impl SelectorSchema for Entry {
        fn droppable(path: &str) -> bool {
            path.is_empty()
        }
    }

    #[test]
    fn validation_rejects_malformed_and_inadmissible_selectors() {
        let cases = [
            (
                json!({"$one": {"type": "Attribute"}, "x": 1}),
                "one",
                "exactly one",
            ),
            (json!({"$some": {"type": "Attribute"}}), "one", "$some"),
            (json!({"$one": "Attribute"}), "one", "object"),
            (json!({"$one": {"type": "Nonsense"}}), "one", "Nonsense"),
            (json!({"$one": {"type": []}}), "one", "type"),
            (
                json!({"$one": {"type": "Attribute", "extra": 1}}),
                "one",
                "extra",
            ),
            (
                json!({"$one": {"type": "Attribute", "where": 3}}),
                "one",
                "where",
            ),
            (
                json!({"$one": {"type": "Attribute", "where": {"name": {"$one": {}}}}}),
                "one",
                "where",
            ),
            (
                json!({"$one": {"type": ["Attribute", "Attribute"]}}),
                "one",
                "twice",
            ),
        ];
        for (selector, path, needle) in cases {
            let s = sample(json!({"one": selector, "many": [], "entries": []}));
            let err = s.validate().unwrap_err();
            assert_eq!(err.path, path, "{selector}");
            assert!(
                matches!(&err.kind, SelectorErrorKind::Invalid(r) if r.contains(needle)),
                "{selector}: {err}"
            );
            // Resolution checks the same rules.
            assert!(matches!(
                s.resolve(&graph()).unwrap_err().kind,
                SelectorErrorKind::Invalid(_)
            ));
        }
        // A position with declared targets admits only those node types.
        let s = sample(json!({"one": "a:b", "many": {"$all": {"type": "Agent"}}, "entries": []}));
        let err = s.validate().unwrap_err();
        assert_eq!(err.path, "many");
        assert!(
            matches!(&err.kind, SelectorErrorKind::Invalid(r) if r.contains("Agent")),
            "{err}"
        );
        // The shape of the value is checked with each selector standing for IDs.
        let s = sample(json!({"one": {"$all": {"type": "Entity"}}, "many": [], "entries": []}));
        assert!(matches!(
            s.validate().unwrap_err().kind,
            SelectorErrorKind::Shape(_)
        ));
        let s = sample(json!({"one": one("x"), "many": [], "entries": [], "extra": 1}));
        assert!(matches!(
            s.validate().unwrap_err().kind,
            SelectorErrorKind::Shape(_)
        ));
    }
}
